module distinct_gcd_count(\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    input [7:0] arr_4,\n    input [7:0] arr_5,\n    input [7:0] arr_6,\n    input [7:0] arr_7,\n    input [3:0] len,\n    output reg [7:0] result\n);\n\n    function automatic [7:0] gcd;\n        input [7:0] a_in;\n        input [7:0] b_in;\n        reg [7:0] a, b, temp;\n        integer k;\n        begin\n            a = a_in;\n            b = b_in;\n            for (k = 0; k < 8; k = k + 1) begin\n                if (b != 8'd0) begin\n                    temp = b;\n                    b = a % temp;\n                    a = temp;\n                end\n            end\n            gcd = a;\n        end\n    endfunction\n\n    integer i, j, k;\n    reg [7:0] arr [0:7];\n    reg [255:0] mask;\n    reg [7:0] current_gcd;\n\n    always @(*) begin\n        arr[0] = arr_0;\n        arr[1] = arr_1;\n        arr[2] = arr_2;\n        arr[3] = arr_3;\n        arr[4] = arr_4;\n        arr[5] = arr_5;\n        arr[6] = arr_6;\n        arr[7] = arr_7;\n\n        mask = 256'd0;\n\n        for (i = 0; i < 8; i = i + 1) begin\n            if (i < len) begin\n                current_gcd = arr[i];\n                mask[current_gcd] = 1'b1;\n                for (j = i + 1; j < 8; j = j + 1) begin\n                    if (j < len) begin\n                        current_gcd = gcd(current_gcd, arr[j]);\n                        mask[current_gcd] = 1'b1;\n                    end\n                end\n            end\n        end\n\n        result = 8'd0;\n        for (k = 0; k < 256; k = k + 1) begin\n            result = result + mask[k];\n        end\n    end\n\nendmodule